1	import { CONFIG } from '../config';
2	import { t, onChange as onLangChange, getLang } from '../i18n';
3	import { openSheet, ui } from './compactUI';
4	import { envClockParts, envHHMM, envPhase } from '../realtime/clock';
5	import { envWx, envCompass, envUvLevel, type EnvIcon } from '../realtime/weatherApi';
6	import { createEnvStore, type EnvStore } from '../realtime/store';
7	
8	/* ===== Giờ + thời tiết thực tế tại Đà Nẵng (D-042) =====
9	   Chỉ báo #envPill luôn hiện + thẻ #envCard (tờ 'env' của compactUI.ts). Đồng hồ chạy mỗi giây theo CONFIG.env.tz, số liệu từ realtime/store.ts.
10	   Chỉ hiển thị: không đọc / ghi thời tiết mô phỏng, thanh Ngày / Đêm hay đèn. Chỉ ghi DOM khi chuỗi đổi (đồng hồ mỗi giây không gây bố trí lại thừa). */
11	
12	export type EnvUI = { store: EnvStore; render(): void; setNow(fn: (() => number) | null): void };
13	
14	/* Biểu tượng nét 24×24 (chép từ prototype; 'cloud', 'fog', 'storm', 'snow' vẽ thêm cùng nét); 'off' = mất kết nối */
15	const RAIN_CLOUD = '<path d="M7 15.5h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 7.3 4.2 4.2 0 0 0 7 15.5z"/>';
16	const ICO: Record<EnvIcon | 'off', string> = {
17	  'clear-d': '<circle cx="12" cy="12" r="4"/><path d="M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7"/>',
18	  'clear-n': '<path d="M19.5 14.2A8 8 0 0 1 9.8 4.5a8 8 0 1 0 9.7 9.7z"/><path d="M17 4.2v2.6M15.7 5.5h2.6"/>',
19	  'cloudy-d': '<path d="M8.2 6.2l-.9-1.5M12.5 5V3.2M16 6.5l1.2-1.3M9 10.2a4 4 0 0 1 7.3-.6"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
20	  'cloudy-n': '<path d="M18.8 8.4a4.6 4.6 0 0 1-5.4-5.6 4.6 4.6 0 0 0-2.2 6.3"/><path d="M7 19.5h10a3.6 3.6 0 0 0 .5-7.16A5 5 0 0 0 7.9 11.6 4 4 0 0 0 7 19.5z"/>',
21	  cloud: '<path d="M7 18h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 9.8 4.2 4.2 0 0 0 7 18z"/>',
22	  rain: RAIN_CLOUD + '<path d="M8.5 18.2l-.9 2.4M12.4 18.2l-.9 2.4M16.3 18.2l-.9 2.4"/>',
23	  fog: '<path d="M7 12.5h10a3.8 3.8 0 0 0 .5-7.56A5.2 5.2 0 0 0 7.6 4.3 4.2 4.2 0 0 0 7 12.5z"/><path d="M4 16h16M6 19.5h12"/>',
24	  storm: RAIN_CLOUD + '<path d="M12.6 16.6l-2 3h3l-2 3"/>',
25	  snow: RAIN_CLOUD + '<path d="M8.5 18.6v.01M12.5 18.6v.01M16.5 18.6v.01M10.5 21.2v.01M14.5 21.2v.01"/>',
26	  off: '<path d="M7 18h10a4 4 0 0 0 .6-7.96A5.5 5.5 0 0 0 7.1 9.2 4.4 4.4 0 0 0 7 18z" opacity=".5"/><path d="M5 4l14 16"/>'
27	};
28	
29	const pad2 = (n: number): string => (n < 10 ? '0' : '') + n;
30	
31	export function setupEnvUI(opts: { live: boolean }): EnvUI {
32	  const cfg = CONFIG.env;
33	  let nowFn: () => number = () => Date.now();   // nguồn giờ của đồng hồ / buổi / trạng thái; test ép bằng setNow
34	  let storage: Storage | null = null;
35	  try { storage = window.localStorage; } catch { /* bộ nhớ trình duyệt bị chặn */ }
36	  const store = createEnvStore({
37	    cfg, live: opts.live,
38	    fetch: (u, i) => fetch(u, i),
39	    now: () => nowFn(),   // cùng nguồn giờ với đồng hồ để trạng thái 'stale' khớp giờ đang hiện
40	    storage,
41	    setTimer: (fn, ms) => window.setTimeout(fn, ms),
42	    clearTimer: (id) => window.clearTimeout(id as number)
43	  });
44	
45	  const root = document.getElementById('env');
46	  if (!root) { store.start(); return { store, render() {}, setNow(fn) { nowFn = fn || (() => Date.now()); } }; }
47	  const q = <T extends Element = HTMLElement>(sel: string): T => root.querySelector<T>(sel);
48	  const qa = (sel: string): HTMLElement[] => Array.from(root.querySelectorAll<HTMLElement>(sel));
49	  const pill = q<HTMLButtonElement>('#envPill'), btnX = q<HTMLButtonElement>('#envX'), scrim = q('#envScrim');
50	  const hmEls = qa('[data-hm]'), ssEls = qa('[data-ss]'), icoEls = qa('[data-ico]'), swaps = qa('.env-swap');
51	  const el = {
52	    temp: q('[data-temp]'), tempN: q('[data-temp-n]'), descShort: q('[data-desc-short]'), desc: q('[data-desc]'), feels: q('[data-feels]'),
53	    date: q('[data-date]'), sunDot: q('[data-sundot]'), sunrise: q('[data-sunrise]'), sunset: q('[data-sunset]'), sunNote: q('[data-sunnote]'),
54	    hum: q('[data-hum]'), wind: q('[data-wind]'), rain: q('[data-rain]'), dir: q('[data-dir]'), cloud: q('[data-cloud]'), uv: q('[data-uv]'), foot: q('[data-foot]')
55	  };
56	  const dirArrow = el.dir.querySelector<SVGElement>('.arrow'), dirText = el.dir.querySelector<HTMLElement>('span');
57	
58	  /* Ghi chỉ khi đổi: đọc textContent / thuộc tính không buộc bố trí lại, ghi thừa thì có */
59	  const setText = (e: Element | null, s: string) => { if (e && e.textContent !== s) e.textContent = s; };
60	  const setData = (e: HTMLElement, k: string, v: string) => { if (e.dataset[k] !== v) e.dataset[k] = v; };
61	  const setStyle = (e: HTMLElement | SVGElement, k: string, v: string) => { if (e.style.getPropertyValue(k) !== v) e.style.setProperty(k, v); };
62	  const valKey = new Map<HTMLElement, string>();
63	  /* Ô số liệu: số + đơn vị nhỏ (<small>) */
64	  const setVal = (e: HTMLElement, main: string, small: string) => {
65	    const k = main + '\u0001' + small;
66	    if (valKey.get(e) === k) return;
67	    valKey.set(e, k);
68	    const nodes: (Node | string)[] = [main];
69	    if (small) { const s = document.createElement('small'); s.textContent = small; nodes.push(s); }
70	    e.replaceChildren(...nodes);
71	  };
72	  let icoKey = '';
73	  const setIcon = (k: EnvIcon | 'off') => { if (k === icoKey) return; icoKey = k; for (const e of icoEls) e.innerHTML = ICO[k]; };
74	
75	  /* Bộ định dạng theo ngôn ngữ (chữ số Latin ở mọi ngôn ngữ), tạo lại khi đổi ngôn ngữ */
76	  let fmtLang = '', fmtDate: Intl.DateTimeFormat, fmtH: Intl.NumberFormat, fmtM: Intl.NumberFormat;
77	  const fmts = () => {
78	    const lang = getLang();
79	    if (lang === fmtLang) return;
80	    fmtLang = lang;
81	    const loc = lang + '-u-nu-latn';
82	    fmtDate = new Intl.DateTimeFormat(loc, { timeZone: cfg.tz, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });
83	    fmtH = new Intl.NumberFormat(loc, { style: 'unit', unit: 'hour', unitDisplay: 'short' });
84	    fmtM = new Intl.NumberFormat(loc, { style: 'unit', unit: 'minute', unitDisplay: 'short' });
85	  };
86	  const dur = (min: number): string => { const h = Math.floor(min / 60), m = min % 60; return (h ? fmtH.format(h) + ' ' : '') + fmtM.format(m); };
87	
88	  /* ----- Vẽ mọi thứ trừ chữ số đồng hồ (gọi khi phút đổi, số liệu / trạng thái đổi, đổi ngôn ngữ) ----- */
89	  const paint = () => {
90	    fmts();
91	    const now = nowFn(), c = envClockParts(new Date(now), cfg.tz), min = c.min;
92	    const data = store.data, st = store.status();
93	    const sr = data && data.sunrise != null ? data.sunrise : cfg.sunFallback[0];
94	    const ss = data && data.sunset != null ? data.sunset : cfg.sunFallback[1];
95	    const day = min >= sr && min < ss;   // ngày / đêm theo đồng hồ, không theo is_day của số liệu (số liệu có thể cũ)
96	    setData(root, 'phase', envPhase(min, sr, ss, cfg.dawnMin, cfg.duskMin));
97	    setData(root, 'state', st);
98	    setText(el.date, fmtDate.format(new Date(now)));
99	    // Vạch mặt trời: chấm ẩn khi ngoài khoảng mọc → lặn
100	    setStyle(el.sunDot, 'inset-inline-start', (Math.max(0, Math.min(1, (min - sr) / (ss - sr))) * 100).toFixed(2) + '%');
101	    setStyle(el.sunDot, 'opacity', day ? '1' : '0');
102	    setText(el.sunrise, t('envSunrise', { t: envHHMM(sr) }));
103	    setText(el.sunset, t('envSunset', { t: envHHMM(ss) }));
104	    setText(el.sunNote, day ? t('envSunLeft', { t: dur(ss - min) }) : t('envSunIn', { t: dur((sr - min + 1440) % 1440) }));
105	    // Chân thẻ
106	    setText(el.foot, st === 'loading' ? t('envLoading')
107	      : st === 'offline' ? t('envOffline')
108	      : st === 'stale' ? t('envStale', { t: envHHMM(data.obsMin) })
109	      : t('envObs', { t: envHHMM(data.obsMin), n: Math.round(cfg.refreshMs / 60000) }));
110	    el.foot.classList.toggle('warn', st === 'stale' || st === 'offline');
111	    const dash = '—';
112	    if (!data) {
113	      if (st === 'offline') {
114	        setIcon('off');
115	        setText(el.temp, '– –'); setText(el.tempN, '– –');
116	        setText(el.desc, t('envNoData')); setText(el.descShort, t('envOffline')); setText(el.feels, t('envClockOk'));
117	        for (const e of [el.hum, el.wind, el.rain, el.cloud, el.uv]) setVal(e, dash, '');
118	        setStyle(dirArrow, 'display', 'none'); setText(dirText, dash);
119	      } else {
120	        // Đang tải: chữ giữ chỗ cho khối xám (.v trong suốt), không phải số liệu
121	        setIcon(day ? 'clear-d' : 'clear-n');
122	        setText(el.temp, '00°'); setText(el.tempN, '00');
123	        setText(el.desc, t('envWxPartly')); setText(el.descShort, t('envLoading')); setText(el.feels, t('envFeels', { t: '00' }));
124	        for (const e of [el.hum, el.cloud]) setVal(e, '00', '%');
125	        setVal(el.wind, '00', t('drSpeedUnit')); setVal(el.rain, '0,0', 'mm'); setVal(el.uv, '0', '');
126	        setStyle(dirArrow, 'display', ''); setText(dirText, t('envDirN'));
127	      }
128	      return;
129	    }
130	    const wx = envWx(data.code, day);
131	    setIcon(wx.icon);
132	    const temp = String(Math.round(data.temp));
133	    setText(el.temp, temp + '°'); setText(el.tempN, temp);
134	    setText(el.desc, t(wx.key)); setText(el.descShort, t(wx.key));
135	    setText(el.feels, t('envFeels', { t: Math.round(data.feels) }));
136	    setVal(el.hum, String(Math.round(data.hum)), '%');
137	    setVal(el.wind, String(Math.round(data.wind)), t('drSpeedUnit'));
138	    setVal(el.rain, data.rain.toLocaleString(fmtLang + '-u-nu-latn', { minimumFractionDigits: 1, maximumFractionDigits: 1 }), 'mm');
139	    setStyle(dirArrow, 'display', '');
140	    setStyle(dirArrow, 'transform', 'rotate(' + Math.round(data.dir + 180) + 'deg)');   // mũi tên chỉ hướng gió thổi tới
141	    setText(dirText, t('envDir' + envCompass(data.dir)));
142	    setVal(el.cloud, String(Math.round(data.cloud)), '%');
143	    if (data.uv == null) setVal(el.uv, dash, '');
144	    else {
145	      const uv = day ? Math.round(data.uv) : 0;   // đêm theo đồng hồ: 0, không mức
146	      const lv = envUvLevel(uv);
147	      setVal(el.uv, String(uv), lv ? t('envUv' + lv) : '');
148	    }
149	  };
150	
151	  /* ----- Đồng hồ: căn mép giây kế tiếp; phút đổi thì vẽ lại phần còn lại ----- */
152	  let lastMin = -1, clockTimer = 0;
153	  const tick = (force: boolean) => {
154	    const c = envClockParts(new Date(nowFn()), cfg.tz);
155	    const hm = envHHMM(c.min), s = pad2(c.s);
156	    for (const e of hmEls) setText(e, hm);
157	    for (const e of ssEls) setText(e, s);
158	    if (force || c.min !== lastMin) { lastMin = c.min; if (!swapTimer) paint(); }
159	  };
160	  const schedule = () => {
161	    window.clearTimeout(clockTimer);
162	    clockTimer = window.setTimeout(() => { tick(false); schedule(); }, 1000 - (Date.now() % 1000) + 5);   // +5 ms: chắc chắn đã qua mép giây
163	  };
164	
165	  /* ----- Số liệu đổi: nhiệt độ và lưới số mờ ra / vào 180 ms (bỏ khi giảm chuyển động) ----- */
166	  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
167	  let swapTimer = 0, shownData = store.data;
168	  const onStore = () => {
169	    const changed = store.data !== shownData;
170	    shownData = store.data;
171	    if (!changed || reduced.matches) { if (!swapTimer) paint(); return; }
172	    if (swapTimer) return;   // đang mờ ra: lúc hiện lại vẽ số liệu mới nhất
173	    for (const e of swaps) e.classList.add('out');
174	    swapTimer = window.setTimeout(() => { swapTimer = 0; paint(); for (const e of swaps) e.classList.remove('out'); }, 180);
175	  };
176	  store.onChange(onStore);
177	  onLangChange(() => tick(true));
178	
179	  /* ----- Mở / đóng (tờ 'env'); khám phá: bỏ focus để Space / mũi tên không bấm lại nút ----- */
180	  const blurInExplore = () => { if (document.body.classList.contains('explore')) (document.activeElement as HTMLElement | null)?.blur(); };
181	  pill.addEventListener('click', () => { openSheet(ui.sheet === 'env' ? 'none' : 'env'); blurInExplore(); });
182	  btnX.addEventListener('click', () => { openSheet('none'); blurInExplore(); });
183	  scrim.addEventListener('pointerdown', (e) => { e.preventDefault(); openSheet('none'); });
184	
185	  /* ----- Tab ẩn: dừng đồng hồ và nhịp lấy số liệu; hiện lại: chạy tiếp (store tự lấy nếu đã quá hạn) ----- */
186	  document.addEventListener('visibilitychange', () => {
187	    const vis = !document.hidden;
188	    store.setVisible(vis);
189	    if (vis) { tick(true); schedule(); } else window.clearTimeout(clockTimer);
190	  });
191	  window.addEventListener('online', () => { void store.refresh(); });
192	
193	  if (document.hidden) store.setVisible(false);
194	  tick(true);
195	  store.start();
196	  if (!document.hidden) schedule();
197	
198	  return {
199	    store,
200	    render: () => tick(true),
201	    setNow(fn: (() => number) | null) { nowFn = fn || (() => Date.now()); tick(true); }
202	  };
203	}
